class TestProvenanceGate:
    """Test _check_prompt_provenance() in shadow and enforce modes."""

    def test_empty_prompt_always_passes(self):
        """No prompt content → no check needed."""
        assert gateway._check_prompt_provenance("some-task", "") is True

    @patch("gateway.SKILLS_DIR", SKILLS_DIR)
    def test_shadow_mode_logs_warning_but_proceeds(self, tmp_path):
        """Shadow mode: unvalidated prompt → warning logged, returns True."""
        # Mock provenance to return unverified
        mock_result = {
            "verified": False,
            "reason": "no matching provenance record found",
            "sha256": "abc123def456" + "0" * 52,
        }

        with patch.dict(sys.modules, {"provenance": MagicMock()}):
            sys.modules["provenance"].verify_prompt_provenance = MagicMock(return_value=mock_result)

            # Ensure shadow mode
            original = gateway._PROVENANCE_ENFORCE
            gateway._PROVENANCE_ENFORCE = False

            shadow_file = tmp_path / "shadow.jsonl"
            with patch.object(gateway, "SHADOW_FILE", shadow_file), \
                 patch.object(gateway, "METRICS_DIR", tmp_path):
                result = gateway._check_prompt_provenance("bridge-tagger", "some prompt text")

            gateway._PROVENANCE_ENFORCE = original

        # Shadow mode: proceeds (True) but should have logged
        assert result is True
        assert shadow_file.exists()
        warning = json.loads(shadow_file.read_text().strip())
        assert warning["event"] == "unvalidated_prompt"
        assert warning["task"] == "bridge-tagger"
        assert warning["enforce"] is False

