class TestScillmEscalateProvenance:
    """Test that _scillm_escalate respects provenance gate."""

    def test_scillm_blocked_in_enforce_mode(self, tmp_path):
        """In enforce mode, scillm returns error for unvalidated task prompt."""
        mock_result = {
            "verified": False,
            "reason": "no matching provenance record found",
            "sha256": "abc123def456" + "0" * 52,
        }

        with patch.dict(sys.modules, {"provenance": MagicMock()}):
            sys.modules["provenance"].verify_prompt_provenance = MagicMock(return_value=mock_result)

            original = gateway._PROVENANCE_ENFORCE
            gateway._PROVENANCE_ENFORCE = True

            with patch.object(gateway, "SHADOW_FILE", tmp_path / "shadow.jsonl"), \
                 patch.object(gateway, "METRICS_DIR", tmp_path):
                # bridge-tagger has a task prompt in _TASK_PROMPTS
                result = gateway._scillm_escalate("test input", "bridge-tagger")

            gateway._PROVENANCE_ENFORCE = original

        assert "error" in result
        assert "Unvalidated prompt" in result["error"]
